		function fn_pwdchk() {
			f = document.srchpwForm;
			if (f.password.value == '') {
				alert('패스워드를 입력해 주세요');
				//f.password.foucs();
				return false;
			}			
			var params = 'idx='+f.idx.value+'&board_db=new_board'+'&pwd='+f.password.value;
			$.ajax({
				url:"/kor/include/pwd_ajax.html",
				dataType:"xml",
				type:"post",
				data:params,
				
				success : function(data) {
					var _check = $(data).find("data").find("total").text();

					if (_check == "1") {
						viewpwd(f.idx.value);
